-- ERM test schema for PostgreSQL 17.6 (step 0.8 of docs/plan-erm-phase-0.md).
-- Same content as mysql.sql, plus a second schema `fracht`, a domain and an enum type.
-- Loaded by tools/dumps.sh into the database `flug`; pg_dump writes every FK as ALTER TABLE.

CREATE TYPE ticket_status AS ENUM ('reserviert', 'bezahlt', 'storniert');
CREATE DOMAIN email_t AS varchar(120) CHECK (VALUE LIKE '%@%');

-- Case: flight example (screenshot). Identity column, comments, UNIQUE.
CREATE TABLE kunde (
    id        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vorname   varchar(50)  NOT NULL,
    nachname  varchar(50)  NOT NULL,
    adresse   varchar(200),
    email     email_t      NOT NULL UNIQUE,
    telefon   varchar(30)
);
COMMENT ON TABLE kunde IS 'Customer who books tickets';
COMMENT ON COLUMN kunde.email IS 'login address, unique';

-- Case: flight example. serial instead of identity (pg_dump writes a sequence + DEFAULT).
CREATE TABLE fluggesellschaft (
    id       serial PRIMARY KEY,
    name     varchar(100) NOT NULL,
    adresse  varchar(200),
    telefon  varchar(30),
    email    varchar(120)
);

-- Case: flight example; 1:n NOT NULL, FK inline as column REFERENCES.
CREATE TABLE flugzeug (
    id                   serial PRIMARY KEY,
    modell               varchar(60)  NOT NULL,
    sitze                smallint     NOT NULL CHECK (sitze > 0),
    geschwindigkeit      numeric(6,1),
    fluggesellschaft_id  integer      NOT NULL REFERENCES fluggesellschaft (id)
);
COMMENT ON COLUMN flugzeug.geschwindigkeit IS 'cruise speed in km/h';

-- Case: flight example; target of two FKs from flug (start/ziel).
CREATE TABLE flughafen (
    id     char(3)      PRIMARY KEY,
    name   varchar(100) NOT NULL,
    stadt  varchar(80)  NOT NULL,
    land   varchar(80)  NOT NULL
);
COMMENT ON COLUMN flughafen.id IS 'IATA code';

-- Case: composite PK (flughafen_id, nummer).
CREATE TABLE gate (
    flughafen_id  char(3)    NOT NULL REFERENCES flughafen (id),
    nummer        varchar(5) NOT NULL,
    terminal      varchar(5),
    PRIMARY KEY (flughafen_id, nummer)
);

-- Case: flight example; two FKs to the same table, nullable composite FK, generated column.
CREATE TABLE flug (
    id                   serial PRIMARY KEY,
    nummer               varchar(8)   NOT NULL,
    preis                numeric(8,2) NOT NULL DEFAULT 0.00,
    start_zeit           timestamp    NOT NULL,
    end_zeit             timestamp    NOT NULL,
    dauer_min            integer GENERATED ALWAYS AS
                         (EXTRACT(EPOCH FROM (end_zeit - start_zeit))::integer / 60) STORED,
    flugzeug_id          integer      NOT NULL,
    start_flughafen_id   char(3)      NOT NULL,
    ziel_flughafen_id    char(3)      NOT NULL,
    gate_flughafen_id    char(3),
    gate_nummer          varchar(5)
);
CREATE INDEX ix_flug_start ON flug (start_flughafen_id, start_zeit);
ALTER TABLE flug
    ADD CONSTRAINT fk_flug_flugzeug FOREIGN KEY (flugzeug_id) REFERENCES flugzeug (id),
    ADD CONSTRAINT fk_flug_start FOREIGN KEY (start_flughafen_id) REFERENCES flughafen (id),
    ADD CONSTRAINT fk_flug_ziel FOREIGN KEY (ziel_flughafen_id) REFERENCES flughafen (id),
    ADD CONSTRAINT fk_flug_gate FOREIGN KEY (gate_flughafen_id, gate_nummer)
        REFERENCES gate (flughafen_id, nummer) ON DELETE SET NULL;

-- Case: flight example; two 1:n NOT NULL FKs, enum type.
CREATE TABLE ticket (
    id         integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    status     ticket_status NOT NULL DEFAULT 'reserviert',
    sitzplatz  varchar(4),
    kunde_id   integer NOT NULL REFERENCES kunde (id) ON DELETE CASCADE,
    flug_id    integer NOT NULL,
    CONSTRAINT fk_ticket_flug FOREIGN KEY (flug_id) REFERENCES flug (id)
);

-- Case: 1:1 by a UNIQUE NOT NULL FK.
CREATE TABLE kunde_konto (
    id             serial PRIMARY KEY,
    kunde_id       integer NOT NULL UNIQUE REFERENCES kunde (id),
    login          varchar(40) NOT NULL,
    passwort_hash  bytea NOT NULL
);

-- Case: PK = FK (1:1 extension, O5).
CREATE TABLE vielflieger (
    kunde_id  integer PRIMARY KEY REFERENCES kunde (id),
    meilen    integer NOT NULL DEFAULT 0,
    stufe     varchar(10) NOT NULL DEFAULT 'basis'
);

-- Case: self-reference.
CREATE TABLE mitarbeiter (
    id               serial PRIMARY KEY,
    name             varchar(100) NOT NULL,
    vorgesetzter_id  integer REFERENCES mitarbeiter (id)
);

-- Case: n:m without extra columns.
CREATE TABLE flug_crew (
    flug_id         integer NOT NULL REFERENCES flug (id),
    mitarbeiter_id  integer NOT NULL REFERENCES mitarbeiter (id),
    PRIMARY KEY (flug_id, mitarbeiter_id)
);

CREATE TABLE extra (
    id           serial PRIMARY KEY,
    bezeichnung  varchar(60) NOT NULL,
    preis        numeric(8,2) NOT NULL
);

-- Case: n:m with extra columns.
CREATE TABLE buchung_extra (
    ticket_id  integer NOT NULL REFERENCES ticket (id),
    extra_id   integer NOT NULL REFERENCES extra (id),
    anzahl     smallint NOT NULL DEFAULT 1,
    preis      numeric(8,2) NOT NULL,
    PRIMARY KEY (ticket_id, extra_id)
);

-- Case: ternary relationship.
CREATE TABLE pilot (
    id      serial PRIMARY KEY,
    name    varchar(100) NOT NULL,
    lizenz  varchar(20) NOT NULL
);
CREATE TABLE rolle (
    id           serial PRIMARY KEY,
    bezeichnung  varchar(40) NOT NULL
);
CREATE TABLE einsatz (
    pilot_id  integer NOT NULL REFERENCES pilot (id),
    flug_id   integer NOT NULL REFERENCES flug (id),
    rolle_id  integer NOT NULL REFERENCES rolle (id),
    stunden   numeric(4,1),
    PRIMARY KEY (pilot_id, flug_id, rolle_id)
);

-- Case: weak entity.
CREATE TABLE sitzplatz (
    flugzeug_id  integer  NOT NULL REFERENCES flugzeug (id) ON DELETE CASCADE,
    reihe        smallint NOT NULL,
    buchstabe    char(1)  NOT NULL,
    klasse       varchar(10) NOT NULL DEFAULT 'economy'
                 CHECK (klasse IN ('economy', 'business', 'first')),
    PRIMARY KEY (flugzeug_id, reihe, buchstabe)
);

-- Case: own schema, quoting with spaces and capitals, umlaut, table without PK,
-- FK to a UNIQUE column, FK across schemas.
CREATE SCHEMA fracht;
COMMENT ON SCHEMA fracht IS 'cargo';
CREATE TABLE fracht."Fracht Stück" (
    "Sendungs Nr"  integer      NOT NULL,
    "Gewicht kg"   numeric(7,2) NOT NULL,
    flug_nummer    varchar(8),
    kunde_email    varchar(120) REFERENCES public.kunde (email)
);
COMMENT ON TABLE fracht."Fracht Stück" IS 'Cargo item; no primary key on purpose';
CREATE TABLE fracht."Container" (
    "ID"      serial PRIMARY KEY,
    flug_id   integer NOT NULL REFERENCES public.flug (id),
    "Typ"     text NOT NULL
);

-- Case: view, trigger function, trigger, function with a $$ body.
CREATE VIEW flugplan AS
    SELECT f.nummer, f.start_flughafen_id AS von, f.ziel_flughafen_id AS nach, f.start_zeit
    FROM flug f;

CREATE FUNCTION ticket_storno() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.status = 'storniert' THEN
        NEW.sitzplatz := NULL; -- comment with ; inside a body
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER ticket_storno BEFORE UPDATE ON ticket
    FOR EACH ROW EXECUTE FUNCTION ticket_storno();

CREATE FUNCTION freie_plaetze(p_flug integer) RETURNS integer LANGUAGE sql AS $body$
    SELECT z.sitze - count(t.id)::integer
    FROM flug f JOIN flugzeug z ON z.id = f.flugzeug_id
    LEFT JOIN ticket t ON t.flug_id = f.id AND t.status <> 'storniert'
    WHERE f.id = p_flug
    GROUP BY z.sitze;
$body$;

